// The bot proves account ownership; the HttpOnly pairing cookie binds that
// approval to the browser that requested it. Telegram and web use one account.
export function createBrowserLogin({escape:e,redraw,onLogin}){
 let ticket=null,error='',busy=false,timer=null,polling=false;
 const $=s=>document.querySelector(s);
 try{ticket=JSON.parse(sessionStorage.getItem('lexora.browser-login'));if(ticket?.expires<Date.now())ticket=null;}catch{}
 function stop(){clearInterval(timer);timer=null;}
 function view(){return `<section class="onboarding bot-onboarding" id="browser-login"><span class="eyebrow">BITTA HISOB · BOT VA SAYT</span><h1>Lexora’ga xush kelibsiz.</h1><p>Telegram’da ro‘yxatdan o‘tgan bo‘lsangiz, shu hisobingiz bilan kiring. Yangi foydalanuvchilar ham avval botda tanishuvdan o‘tadi.</p>${ticket?`<div class="panel"><p>Botdagi kod shu kod bilan bir xil bo‘lishi kerak:</p><strong class="pair-code">${e(ticket.code)}</strong><p>Faqat o‘zingiz boshlagan kirishni tasdiqlang. Keyin shu sahifaga qayting.</p><a class="btn primary" href="${e(ticket.url)}" target="_blank" rel="noopener noreferrer">Telegram botga o‘tish</a><button class="btn" id="browser-check">Tasdiqladim — tekshirish</button><p role="status">${error?e(error):'Botdagi tasdiq kutilmoqda. Havola 10 daqiqa amal qiladi.'}</p></div>`:''}<button class="btn ${ticket?'':'primary'}" id="browser-begin" ${busy?'disabled':''}>${busy?'Tayyorlanmoqda…':ticket?'Yangi kirish havolasi':'Telegram orqali kirish'}</button><p class="error" role="alert">${!ticket?e(error):''}</p><details><summary>Telegram ochilmasa</summary><p>Botni Telegram qidiruvida <b>@lexora_academy_bot</b> deb toping. Kirish havolasi tayyorlangach quyidagi buyruqni botga yuboring:</p>${ticket?`<code>/start login_${e(ticket.id)}</code>`:'<p>Avval “Telegram orqali kirish”ni bosing.</p>'}</details></section>`;}
 async function post(path,body){const r=await fetch('/api/auth/browser/'+path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw Error(data.error||'Kirish vaqtincha ishlamadi.');return data;}
 async function check(){if(polling||!ticket||!$('#browser-login')||document.hidden)return;polling=true;try{const result=await post('status',{id:ticket.id});if(result.status==='approved'){stop();ticket=null;sessionStorage.removeItem('lexora.browser-login');await onLogin();}}catch(er){error=er.message;stop();redraw();}finally{polling=false;}}
 function mount(){if(!$('#browser-login')){stop();return;}$('#browser-begin').onclick=async()=>{if(busy)return;busy=true;error='';stop();redraw();try{ticket=await post('start',{});sessionStorage.setItem('lexora.browser-login',JSON.stringify(ticket));}catch(er){error=er.message;}finally{busy=false;redraw();}};if(ticket){$('#browser-check').onclick=check;if(!timer&&!error)timer=setInterval(check,3000);}}
 return {view,mount};
}
